INSERT INTO incident (id, site_id, equipment_id, work_plan_id, occurred_at, victim_name, severity, leave_days, accident_type, description, cause, prevention, report_due_date, report_status, follow_up_assessment_id, created_at) VALUES
  (2, 1, 7, 11, ((pg_temp.saife_wd((CURRENT_DATE - 240)) + TIME '10:40') AT TIME ZONE 'Asia/Seoul'), '최OO', 'LOST_TIME', 2, 'CAUGHT', '금형 교체 후 시운전 중 소재 위치를 손으로 바로잡다가 왼손 검지 끝이 상, 하 금형 사이에 끼임', '불안전 상태: 양수조작 버튼이 금형 가까이 있어 한 손으로 조작할 수 있었음' || chr(10) || '불안전 행동: 시운전 중 소재 위치를 수공구 없이 손으로 바로잡음', '1. 시운전 중 소재 위치 조정은 수공구 사용, 양수조작 버튼 위치 재설정 (담당 가공반장 이영희, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 240)) + 14)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 240)))), 'YYYY-MM-DD') || ')', NULL, 'NOT_REQUIRED', 20, ((pg_temp.saife_wd((CURRENT_DATE - 240)) + TIME '11:23') AT TIME ZONE 'Asia/Seoul')),
  (3, 1, 10, NULL, ((pg_temp.saife_wd((CURRENT_DATE - 115)) + TIME '14:10') AT TIME ZONE 'Asia/Seoul'), '장OO', 'LOST_TIME', 1, 'DROP', '탁상 연삭기로 공구를 연마하던 중 숫돌 파편이 튀어 오른쪽 눈 주위에 맞음', '불안전 상태: 숫돌 덮개 조정편과 숫돌 사이 간격이 벌어져 있었음' || chr(10) || '불안전 행동: 보안경을 쓰지 않고 연마함', '1. 숫돌 교체, 조정편 간격 재조정, 사용 전 1분 시운전 (담당 가공반장 이영희, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 115)) + 7)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 115)))), 'YYYY-MM-DD') || ')' || chr(10) || '2. 연삭기 투명 비산 방지판 설치 (담당 설비팀장 박민수, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 115)) + 14)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 115)))), 'YYYY-MM-DD') || ')', NULL, 'NOT_REQUIRED', 21, ((pg_temp.saife_wd((CURRENT_DATE - 115)) + TIME '15:37') AT TIME ZONE 'Asia/Seoul')),
  (4, 1, 17, NULL, ((pg_temp.saife_wd((CURRENT_DATE - 60)) + TIME '16:30') AT TIME ZONE 'Asia/Seoul'), NULL, 'NEAR_MISS', 0, 'STRUCK', '창고동 출입구에서 지게차가 후진하던 중 보행 작업자와 약 1m 거리까지 접근, 접촉 없음', '불안전 상태: 후진 경보기가 작동하지 않았고, 출입구 보행 통로가 바닥에 구획되어 있지 않았음' || chr(10) || '불안전 행동: 운전원이 후방을 확인하지 않고 후진함', '1. 지게차 후진 경보기, 후방 카메라 수리 (담당 설비팀장 박민수, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 60)) + 7)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 60)))), 'YYYY-MM-DD') || ')' || chr(10) || '2. 창고동 출입구 보행 통로 구획선 도색 (담당 창고반장 최동훈, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 60)) + 14)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 60)))), 'YYYY-MM-DD') || ')', NULL, 'NOT_REQUIRED', 22, ((pg_temp.saife_wd((CURRENT_DATE - 60)) + TIME '17:31') AT TIME ZONE 'Asia/Seoul')),
  (5, 1, 13, NULL, ((pg_temp.saife_wd((CURRENT_DATE - 150)) + TIME '15:20') AT TIME ZONE 'Asia/Seoul'), '한OO', 'LOST_TIME', 6, 'FIRE', 'CO2 용접 중 불티가 작업대 아래 유기용제 묻은 걸레에 옮겨 붙었고, 불을 끄던 작업자가 오른손등에 화상', '불안전 상태: 용접 작업 반경 안에 유기용제 묻은 걸레가 있었고 방화포가 없었음' || chr(10) || '불안전 행동: 화재감시자 없이 1인으로 용접함', '1. 용접 반경 안 유기용제, 걸레 반입 금지 표지와 정리 (담당 용접반장 정민준, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd(((date_trunc('month', CURRENT_DATE) - INTERVAL '6 months')::date + 9)) + 14)), pg_temp.saife_next(pg_temp.saife_wd(((date_trunc('month', CURRENT_DATE) - INTERVAL '6 months')::date + 9)))), 'YYYY-MM-DD') || ')' || chr(10) || '2. 용접 작업 시 화재감시자 배치, 방화포 사용 (담당 용접반장 정민준, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 150)) + 7)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 150)))), 'YYYY-MM-DD') || ')' || chr(10) || '3. 용접구역 유기용제 걸레 전용 밀폐 용기 비치 (담당 용접반장 정민준, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 150)) + 14)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 150)))), 'YYYY-MM-DD') || ')', (pg_temp.saife_wd((CURRENT_DATE - 150)) + INTERVAL '1 month')::date, 'SUBMITTED', 23, ((pg_temp.saife_wd((CURRENT_DATE - 150)) + TIME '15:57') AT TIME ZONE 'Asia/Seoul')),
  (6, 1, 16, 37, ((pg_temp.saife_wd((CURRENT_DATE - 20)) + TIME '09:50') AT TIME ZONE 'Asia/Seoul'), '서OO', 'LOST_TIME', 42, 'DROP', '금형(약 1.2톤) 인양 중 해지장치가 부러진 훅에서 슬링 한쪽이 벗겨져 금형이 기울며 흔들렸고, 기운 금형 모서리가 신호수 오른발등을 침, 중족골 골절', '불안전 상태: 훅 해지장치 스프링이 부러져 있었고, 인양물 주변 출입 통제선이 없었음' || chr(10) || '불안전 행동: 인양 전 해지장치를 확인하지 않고 인양했고, 신호수가 인양물 가까이 서 있었음', '1. 천장크레인 훅 해지장치 교체 (담당 설비팀장 박민수, 기한 ' || to_char(GREATEST(pg_temp.saife_wd((pg_temp.saife_wd((CURRENT_DATE - 20)) + 1)), pg_temp.saife_next(pg_temp.saife_wd((CURRENT_DATE - 20)))), 'YYYY-MM-DD') || ')' || chr(10) || '2. 줄걸이 용구 사용 전 점검표 도입, 인양 전 해지장치 확인 (담당 용접반장 정민준, 기한 ' || to_char(pg_temp.saife_wd((CURRENT_DATE + 3)), 'YYYY-MM-DD') || ')' || chr(10) || '3. 인양 작업 신호수 위치 지정, 인양물 주변 출입 금지 교육 (담당 안전관리자 홍길동, 기한 ' || to_char(pg_temp.saife_wd((CURRENT_DATE + 25)), 'YYYY-MM-DD') || ')', (pg_temp.saife_wd((CURRENT_DATE - 20)) + INTERVAL '1 month')::date, 'REQUIRED', 24, ((pg_temp.saife_wd((CURRENT_DATE - 20)) + TIME '11:17') AT TIME ZONE 'Asia/Seoul'));
