-- =====================================================================
-- 데모 규모 시드 (2/2): 작업 전 점검(TBM, 제38조 작업계획서), 사고
--
-- 작업 전 점검 41건(V10의 1건 포함 42): 지난 작업일은 전부 완료(CLOSED), 승인(오늘 이후),
-- 승인 대기(오늘, 다음 작업일), 작업 보류(사고 6 후속). 지게차 하역과 천장크레인 인양은 안전보건규칙
-- 제38조 대상이라 서식 이름이 작업계획서로 갈리고, 관리감독자가 작업지휘자(제39조)를 맡는다.
-- 승인자는 그 작업의 관리감독자(반장, 팀장)다. 승인은 전 평일 오후 또는 당일 07:30~08:15,
-- TBM은 당일 07:50~08:40(승인 뒤)이다. 미이행 조치가 남은 설비의 작업은 승인 조건(잠정조치)을 단다.
--
-- 사고 5건(V10의 1건 포함 6): 끼임 휴업 2일, 물체에 맞음 휴업 1일, 부딪힘 아차사고, 화재 휴업 6일(조사표 제출),
-- 천장크레인 물체에 맞음 휴업 42일(조사표 작성 필요, 수시평가 작성 중, 다음 인양 작업 보류).
-- 원인은 불안전 상태와 불안전 행동으로 나눈 사실, 재발방지는 "무엇을 (담당, 기한 YYYY-MM-DD)" 형식이다.
-- =====================================================================

-- 평일 보정 함수(이 마이그레이션 세션 안에서만 쓴다). 주말과 공휴일(2025~2027, 대체공휴일, 근로자의 날)을
-- 피한다. 오늘보다 앞선 날은 직전 평일로, 오늘 이후는 다음 평일로 민다. 날짜 순서는 뒤집히지 않는다
CREATE OR REPLACE FUNCTION pg_temp.saife_wd(d date) RETURNS date LANGUAGE plpgsql STABLE AS $$
DECLARE
  r    date := d;
  step int  := CASE WHEN d < CURRENT_DATE THEN -1 ELSE 1 END;
BEGIN
  WHILE EXTRACT(ISODOW FROM r) >= 6 OR r = ANY ('{2025-01-01,2025-01-27,2025-01-28,2025-01-29,2025-01-30,2025-03-01,2025-03-03,2025-05-01,2025-05-05,2025-05-06,2025-06-03,2025-06-06,2025-08-15,2025-10-03,2025-10-05,2025-10-06,2025-10-07,2025-10-08,2025-10-09,2025-12-25,2026-01-01,2026-02-16,2026-02-17,2026-02-18,2026-03-01,2026-03-02,2026-05-01,2026-05-05,2026-05-24,2026-05-25,2026-06-03,2026-06-06,2026-07-17,2026-08-15,2026-08-17,2026-09-24,2026-09-25,2026-09-26,2026-10-03,2026-10-05,2026-10-09,2026-12-25,2027-01-01,2027-02-06,2027-02-07,2027-02-08,2027-02-09,2027-03-01,2027-05-01,2027-05-05,2027-05-13,2027-06-06,2027-07-17,2027-08-15,2027-08-16,2027-09-14,2027-09-15,2027-09-16,2027-10-03,2027-10-04,2027-10-09,2027-10-11,2027-12-25,2027-12-27}'::date[]) LOOP
    r := r + step;
  END LOOP;
  RETURN r;
END $$;

-- 다음 평일(그날 제외)
CREATE OR REPLACE FUNCTION pg_temp.saife_next(d date) RETURNS date LANGUAGE plpgsql STABLE AS $$
DECLARE
  r date := d + 1;
BEGIN
  WHILE EXTRACT(ISODOW FROM r) >= 6 OR r = ANY ('{2025-01-01,2025-01-27,2025-01-28,2025-01-29,2025-01-30,2025-03-01,2025-03-03,2025-05-01,2025-05-05,2025-05-06,2025-06-03,2025-06-06,2025-08-15,2025-10-03,2025-10-05,2025-10-06,2025-10-07,2025-10-08,2025-10-09,2025-12-25,2026-01-01,2026-02-16,2026-02-17,2026-02-18,2026-03-01,2026-03-02,2026-05-01,2026-05-05,2026-05-24,2026-05-25,2026-06-03,2026-06-06,2026-07-17,2026-08-15,2026-08-17,2026-09-24,2026-09-25,2026-09-26,2026-10-03,2026-10-05,2026-10-09,2026-12-25,2027-01-01,2027-02-06,2027-02-07,2027-02-08,2027-02-09,2027-03-01,2027-05-01,2027-05-05,2027-05-13,2027-06-06,2027-07-17,2027-08-15,2027-08-16,2027-09-14,2027-09-15,2027-09-16,2027-10-03,2027-10-04,2027-10-09,2027-10-11,2027-12-25,2027-12-27}'::date[]) LOOP
    r := r + 1;
  END LOOP;
  RETURN r;
END $$;

-- 직전 평일(그날 제외). 작업 전 점검은 전 평일 오후에 작성한다
CREATE OR REPLACE FUNCTION pg_temp.saife_prev(d date) RETURNS date LANGUAGE plpgsql STABLE AS $$
DECLARE
  r date := d - 1;
BEGIN
  WHILE EXTRACT(ISODOW FROM r) >= 6 OR r = ANY ('{2025-01-01,2025-01-27,2025-01-28,2025-01-29,2025-01-30,2025-03-01,2025-03-03,2025-05-01,2025-05-05,2025-05-06,2025-06-03,2025-06-06,2025-08-15,2025-10-03,2025-10-05,2025-10-06,2025-10-07,2025-10-08,2025-10-09,2025-12-25,2026-01-01,2026-02-16,2026-02-17,2026-02-18,2026-03-01,2026-03-02,2026-05-01,2026-05-05,2026-05-24,2026-05-25,2026-06-03,2026-06-06,2026-07-17,2026-08-15,2026-08-17,2026-09-24,2026-09-25,2026-09-26,2026-10-03,2026-10-05,2026-10-09,2026-12-25,2027-01-01,2027-02-06,2027-02-07,2027-02-08,2027-02-09,2027-03-01,2027-05-01,2027-05-05,2027-05-13,2027-06-06,2027-07-17,2027-08-15,2027-08-16,2027-09-14,2027-09-15,2027-09-16,2027-10-03,2027-10-04,2027-10-09,2027-10-11,2027-12-25,2027-12-27}'::date[]) LOOP
    r := r - 1;
  END LOOP;
  RETURN r;
END $$;

-- ── 작업 전 점검 ───────────────────────────────────────────────────
-- 1번(V10, 사고 1의 고소작업대 조명 교체)은 날짜, 시각, 작업자, 현장 확인을 다시 고정한다
UPDATE work_plan SET work_date = pg_temp.saife_wd((CURRENT_DATE - 45)), work_hours = 4.0, method = '고소작업대로 상승, 기존 조명 탈거, 신규 조명 설치와 결선, 점등 확인', notes = '작업대 결손 구간 출입 금지', briefing = '작업: 2층 조립구역 조명 교체 / 공장동 2층 조립구역 / ' || to_char(pg_temp.saife_wd((CURRENT_DATE - 45)), 'YYYY-MM-DD') || chr(10) || '작업자: 박민수 설비팀장, 이도현 기사' || chr(10) || '대상 설비: 고소작업대 (공장동 2층 조립구역)' || chr(10) || '' || chr(10) || '위험 포인트' || chr(10) || '1. 작업대 안전난간이 빠진 곳으로 떨어질 수 있습니다' || chr(10) || '2. 작업 구역이 정리되지 않으면 걸려 넘어질 수 있습니다' || chr(10) || '' || chr(10) || '지킬 것' || chr(10) || '1. 작업대 안전난간을 보수한 뒤 올라갑니다' || chr(10) || '2. 안전모, 안전대를 착용합니다' || chr(10) || '미이행 조치: 고소작업대 작업대 안전난간 보수 (기한 ' || to_char(pg_temp.saife_wd((CURRENT_DATE - 55)), 'YYYY-MM-DD') || ')' || chr(10) || '' || chr(10) || '위험하면 작업을 멈추고 관리감독자에게 알립니다.', briefing_ack_at = ((pg_temp.saife_wd((CURRENT_DATE - 45)) + TIME '08:39') AT TIME ZONE 'Asia/Seoul'), status = 'CLOSED', approval_note = '결손 구간 출입 금지 표시, 안전대 상시 체결', approved_by = '박민수', approved_at = ((pg_temp.saife_prev(pg_temp.saife_wd((CURRENT_DATE - 45))) + TIME '15:33') AT TIME ZONE 'Asia/Seoul'), closed_at = ((pg_temp.saife_wd((CURRENT_DATE - 45)) + TIME '16:28') AT TIME ZONE 'Asia/Seoul'), warning_note = NULL, created_at = ((pg_temp.saife_prev(pg_temp.saife_wd((CURRENT_DATE - 45))) + TIME '13:16') AT TIME ZONE 'Asia/Seoul') WHERE id = 1;
DELETE FROM work_plan_hazard WHERE work_plan_id = 1;
SELECT setval('work_plan_id_seq', 42, true);

-- ── 사고 ───────────────────────────────────────────────────────────
SELECT setval('incident_id_seq', 6, true);

DROP FUNCTION pg_temp.saife_prev(date);
DROP FUNCTION pg_temp.saife_next(date);
DROP FUNCTION pg_temp.saife_wd(date);

